describe('WK-0160 D8: env wiring -- runDispatch() real workerEnv carries NO_PROXY/no_proxy (pipeline.ts:1018-1021)', () => {
  afterEach(() => {
    vi.restoreAllMocks();
  });

  /** A minimal, known-good fixture repo -- mirrors dispatch-v2-e2e.test.ts's setupS3Repo defaults (pi family, deepseek/openrouter, no credentials, web:false, mode:implement) so runDispatch() reaches spawnIsolated without any unrelated refusal gate tripping first. */
  async function setupEnvWiringRepo(): Promise<string> {
    const repoRoot = await createTempDir('kb-wk0160-envwiring-');
    execFileSync('git', ['init'], { cwd: repoRoot });
    execFileSync('git', ['config', 'user.email', 'test@example.com'], { cwd: repoRoot });
    execFileSync('git', ['config', 'user.name', 'Test User'], { cwd: repoRoot });

    const hoContent = `---
id: HO-WK0160-ENV
title: WK-0160 D8 env-wiring fixture
mode: implement
write_scope: ["src/"]
base_ref: null
web: false
credentials: []
data_mounts: []
read_first: []
vars: []
work_item: WK-9160
acceptance:
  - "AC-1: placeholder -- spawnIsolated is mocked, no worker actually runs"
validation: ["true"]
status: draft
---

## Task
Placeholder fixture for the WK-0160 D8 env-wiring test. spawnIsolated is
mocked below, so this body is never read by a real worker.
`;
    await mkdir(join(repoRoot, 'wiki', 'handoffs'), { recursive: true });
    await writeFile(join(repoRoot, 'wiki', 'handoffs', 'HO-WK0160-ENV.md'), hoContent, 'utf8');
    await writeFile(join(repoRoot, 'README.md'), 'kb-wk0160-envwiring-fixture\n', 'utf8');

    // WK-0116: mode=implement requires work_item to resolve to a real initiative.
    await mkdir(join(repoRoot, 'wiki', 'issues'), { recursive: true });
    await writeFile(
      join(repoRoot, 'wiki', 'issues', 'WK-9160.md'),
      '---\nid: "WK-9160"\ntitle: "Fixture WK"\nstatus: todo\ninitiative: IN-9160\n---\n\n# WK-9160: Fixture\n',
      'utf8',
    );
    await mkdir(join(repoRoot, 'wiki', 'initiatives'), { recursive: true });
    await writeFile(
      join(repoRoot, 'wiki', 'initiatives', 'IN-9160.md'),
      '---\nid: "IN-9160"\ntitle: "Fixture initiative"\nstatus: todo\n---\n\n# IN-9160: Fixture\n',
      'utf8',
    );

    await mkdir(join(repoRoot, 'wiki', '.dispatch'), { recursive: true });
    const models = { deepseek: { available_on: ['openrouter'], model_id: 'deepseek/deepseek-v4-flash-0731' } };
    const backends = {
      openrouter: { family: 'pi', base_url: 'https://openrouter.ai/api/v1', api_key_env: 'OPENROUTER_API_KEY', secrets_file: null },
    };
    const profiles = { schema_version: 1 };
    await writeFile(join(repoRoot, 'wiki', '.dispatch', 'models.json'), JSON.stringify(models, null, 2), 'utf8');
    await writeFile(join(repoRoot, 'wiki', '.dispatch', 'backends.json'), JSON.stringify(backends, null, 2), 'utf8');
    await writeFile(join(repoRoot, 'wiki', '.dispatch', 'profiles.json'), JSON.stringify(profiles, null, 2), 'utf8');

    execFileSync('git', ['add', '-A'], { cwd: repoRoot });
    execFileSync('git', ['commit', '-m', 'initial commit'], { cwd: repoRoot });

    // WK-0152: stamp base_sha = HEAD, then commit again (mirrors
    // dispatch-v2-e2e.test.ts's stampHandoff -- admission.ts's BASE_DRIFT
    // gate refuses a handoff with no valid base_sha).
    const head = execFileSync('git', ['rev-parse', 'HEAD'], { cwd: repoRoot }).toString().trim();
    const hoPath = join(repoRoot, 'wiki', 'handoffs', 'HO-WK0160-ENV.md');
    const stamped = (await readFile(hoPath, 'utf8')).replace('base_ref: null\n', `base_ref: null\nbase_sha: "${head}"\n`);
    await writeFile(hoPath, stamped, 'utf8');
    execFileSync('git', ['add', '-A'], { cwd: repoRoot });
    execFileSync('git', ['commit', '-m', 'stamp'], { cwd: repoRoot });

    return repoRoot;
  }

  it('captures the real workerEnv the pipeline builds and asserts NO_PROXY/no_proxy = 127.0.0.1,localhost', async () => {
    const repoRoot = await setupEnvWiringRepo();
    let capturedEnv: Record<string, string> | undefined;
    vi.spyOn(spawnIsolatedModule, 'spawnIsolated').mockImplementation(async (plan, opts) => {
      capturedEnv = plan.env;
      if (opts?.stdoutLogPath) {
        await writeFile(opts.stdoutLogPath, readFixtureFile('pi-output-vllm-qwen25.jsonl'), 'utf8');
      }
      return {
        ok: true,
        data: { stdout: '', stderr: '', exitCode: 0, signal: null, truncated: false, timedOut: false, streamDrainTimedOut: false },
      };
    });

    try {
      const result = await runDispatch({
        dir: repoRoot,
        handoff: 'wiki/handoffs/HO-WK0160-ENV.md',
        model: 'deepseek',
        backend: 'openrouter',
        preflight: false,
      });
      expect(result.ok).toBe(true);
      if (!result.ok) return;

      expect(capturedEnv).toBeDefined();
      expect(capturedEnv!.NO_PROXY).toBe('127.0.0.1,localhost');
      expect(capturedEnv!.no_proxy).toBe('127.0.0.1,localhost');
      // The other half of the same wiring: the proxy address these two vars
      // exempt loopback FROM.
      expect(capturedEnv!.HTTP_PROXY).toBe(`http://127.0.0.1:${TUNNEL_RELAY_PORT}`);
      expect(capturedEnv!.https_proxy).toBe(`http://127.0.0.1:${TUNNEL_RELAY_PORT}`);
    } finally {
      await rm(repoRoot, { recursive: true, force: true });
    }
  });
});
